354	    public boolean isBound() {
355	        return stated && status != ClaimStatus.PENDING;
356	    }
357	    /** Bind it to a figure (null: n/a), or leave it unbound (live) when {@code stated} is false. */
358	    public void bind(boolean stated, BigDecimal statedDue) {
359	        this.stated = stated;
360	        this.statedDue = stated ? statedDue : null;
361	    }
362	    /**
363	     * Whether it counts toward its person's claimed and due-total, the sheet's totals and a
364	     * period's total: OPEN, PENDING and SETTLED do, except an OPEN or PENDING one dated within one
365	     * of its person's holds ({@code heldOnDate}), unless a statement binds it; and never one
366	     * deferred on {@code today}.
367	     */
368	    public boolean counts(boolean heldOnDate, LocalDate today) {
369	        if (isDeferredOn(today)) return false;
370	        return status == ClaimStatus.SETTLED || (isOpen() && (isBound() || !heldOnDate));
371	    }
372	    /**
373	     * Whether it counts toward a period's total as it was at the period's end, when its status then
374	     * was {@code statusThen} (null: it did not exist yet): as {@link #counts} with that status, its
375	     * statement binding and deferral as they are now.
376	     */
377	    public boolean countsAsOf(ClaimStatus statusThen, boolean heldOnDate, LocalDate today) {
378	        if (statusThen == null || isDeferredOn(today)) return false;
379	        boolean openThen = statusThen == ClaimStatus.OPEN || statusThen == ClaimStatus.PENDING;
380	        return statusThen == ClaimStatus.SETTLED || (openThen && (isBound() || !heldOnDate));
381	    }
382	    /** Whether it is open: OPEN, or PENDING a steward's approval. */
383	    public boolean isOpen() {
384	        return status == ClaimStatus.OPEN || status == ClaimStatus.PENDING;
385	    }
386	    /** Only a draft may be edited; to change an open claim, void it and add a new one. */
387	    public void checkEditable() throws InvalidClaimStatusException {
388	        if (status != ClaimStatus.DRAFT) throw new InvalidClaimStatusException(status);
389	    }
390	
391	    /** A steward's approval of a PENDING claim: it is settled, its due fixed at {@code due}. */
392	    public void approve(BigDecimal due) throws InvalidClaimStatusException {
393	        if (status != ClaimStatus.PENDING) throw new InvalidClaimStatusException(status, ClaimStatus.SETTLED);
394	        status = ClaimStatus.SETTLED;
395	        settledDue = due;
396	    }
397	    /** A steward's rejection of a PENDING claim: it is OPEN again, bound again by its statement. */
398	    public void reject() throws InvalidClaimStatusException {
399	        if (status != ClaimStatus.PENDING) throw new InvalidClaimStatusException(status, ClaimStatus.OPEN);
400	        status = ClaimStatus.OPEN;
401	    }
