403	    /** Move to the next status, when the current one allows it. */
404	    public void moveTo(ClaimStatus next) throws InvalidClaimStatusException {
405	        if (!status.canMoveTo(next)) throw new InvalidClaimStatusException(status, next);
406	        status = next;
