429	    private static final RowMapper<Claim> ROW = (rs, n) -> {
430	        Claim claim = new Claim(rs.getLong("id"),
431	            rs.getString("sheet_id"), rs.getLong("person_id"), rs.getBigDecimal("amount"),
432	            rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
433	            ClaimStatus.valueOf(rs.getString("status")),
434	            rs.getString("claim_number"), rs.getBigDecimal("settled_due"),
435	            rs.getString("opened_by"));
436	        claim.bind(rs.getBoolean("stated"), rs.getBigDecimal("stated_due"));
437	        claim.setCorrects(rs.getString("corrects"));
438	        claim.setDueBy(rs.getDate("due_by").toLocalDate());
439	        java.sql.Date deferred = rs.getDate("deferred_until");
440	        claim.setDeferredUntil(deferred == null ? null : deferred.toLocalDate());
441	        claim.setProofs(rs.getInt("proofs"));
442	        java.sql.Date corrected = rs.getDate("corrected_date");
