463	    }
464	
465	    /** The claim with this id on the sheet, or null when there is none. */
466	    public Claim find(String sheetId, long id) {
467	        List<Claim> found = jdbc.query(
468	                "SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
469	        return found.isEmpty() ? null : found.get(0);
470	    }
471	
472	    /**
473	     * Mark the claim OPEN in the store when it is still DRAFT there, holding its row until the
474	     * request commits so two opens of the same claim cannot both go through; false when another
475	     * request changed it first.
476	     */
477	    public boolean markOpened(Claim claim) {
478	        return jdbc.update("UPDATE claim SET status = 'OPEN' WHERE id = ? AND sheet_id = ? AND status = 'DRAFT'",
479	                claim.getId(), claim.getSheetId()) == 1;
480	    }
481	
482	    /**
483	     * The sheet's next claim number, taken in one statement so two claims opened at the same
484	     * moment never share a number; it is never given out again.
485	     */
486	    public int nextNumber(String sheetId) {
487	        return jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE"
488	                + " (UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)",
489	                Integer.class, sheetId);
490	    }
491	
492	    /**
493	     * The next number in one period's sequence on the sheet ({@code sequence} '' for claims in no
494	     * period), counting from 1; taken in one statement so two claims opened at the same moment
495	     * never share a number, and never given out again.
496	     */
497	    public int nextNumberIn(String sheetId, String sequence) {
498	        jdbc.update("MERGE INTO period_number p USING (VALUES (CAST(? AS VARCHAR(200)), CAST(? AS VARCHAR(200)))) v (sheet_id, seq_name)"
499	                + " ON p.sheet_id = v.sheet_id AND p.seq_name = v.seq_name"
500	                + " WHEN NOT MATCHED THEN INSERT (sheet_id, seq_name, last_number) VALUES (v.sheet_id, v.seq_name, 0)",
501	                sheetId, sequence);
502	        return jdbc.queryForObject("SELECT last_number FROM FINAL TABLE"
503	                + " (UPDATE period_number SET last_number = last_number + 1 WHERE sheet_id = ? AND seq_name = ?)",
504	                Integer.class, sheetId, sequence);
505	    }
506	
507	    /** The sheet's next place in its claims list, taken in one statement; never given out again. */
508	    private long nextListed(String sheetId) {
509	        return jdbc.queryForObject("SELECT last_claim_listed FROM FINAL TABLE"
510	                + " (UPDATE sheet SET last_claim_listed = last_claim_listed + 1 WHERE id = ?)",
511	                Long.class, sheetId);
512	    }
513	
514	    /** Insert a new claim (assigning its id) or update an existing one. */
515	    public void save(Claim claim) {
516	        if (claim.getId() != null) {
517	            if (claim.isRelisted()) {
518	                jdbc.update("UPDATE claim SET person_id = ?, listed = ? WHERE id = ? AND sheet_id = ?",
519	                        claim.getPersonId(), nextListed(claim.getSheetId()), claim.getId(), claim.getSheetId());
520	            }
521	            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, claim_number = ?, settled_due = ?, opened_by = ?, stated = ?, stated_due = ?, corrects = ?, deferred_until = ?, proofs = ? WHERE id = ? AND sheet_id = ?",
522	                    claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(),
523	                    claim.getStatus().name(), claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(),
524	                    claim.isStated(), claim.getStatedDue(), claim.getCorrects(),
525	                    claim.getDeferredUntil() == null ? null : Date.valueOf(claim.getDeferredUntil()), claim.getProofs(), claim.getId(),
526	                    claim.getSheetId());
527	            return;
528	        }
529	        long listed = nextListed(claim.getSheetId());
530	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
531	        jdbc.update(con -> {
532	            PreparedStatement ps = con.prepareStatement(
533	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, corrects, listed, due_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
534	                    Statement.RETURN_GENERATED_KEYS);
535	            ps.setString(1, claim.getSheetId());
536	            ps.setLong(2, claim.getPersonId());
537	            ps.setBigDecimal(3, claim.getAmount());
538	            ps.setDate(4, Date.valueOf(claim.getDate()));
539	            ps.setString(5, claim.getNote());
540	            ps.setString(6, claim.getStatus().name());
541	            ps.setString(7, claim.getCorrects());
542	            ps.setLong(8, listed);
543	            ps.setDate(9, Date.valueOf(claim.getDueBy()));
544	            return ps;
545	        }, keys);
546	        claim.setId(keys.getKey().longValue());
547	    }
548	}
