785	package net.officefloor.hq.app.claim;
786	
787	import java.math.BigDecimal;
788	import java.math.RoundingMode;
789	import java.time.LocalDate;
790	import java.time.temporal.ChronoUnit;
791	import java.util.List;
792	import net.officefloor.hq.app.rate.Rate;
793	import net.officefloor.hq.app.setting.Settings;
794	
795	/**
796	 * A claim's due figure, as the screen shows it: the due fixed when it was settled, else the figure
797	 * its person's last statement bound it to (never while it is PENDING), else its live due: its amount times its grade's rate in
798	 * force on its date, divided by 100 and rounded to two decimals, raised to the sheet's floor when
799	 * below it (a correction, a negative amount, has no floor and no late charge). Null for n/a (no
800	 * floor applies to n/a). Every rounding of a claim's live figures is by the sheet's policy date
801	 * ({@link Settings#rounding}): half up when the claim is dated before it, half to even on or after;
802	 * a correction rounds by the date of the claim it corrects.
803	 */
804	public final class ClaimFigure {
805	    private ClaimFigure() {}
806	
807	    public static BigDecimal of(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
808	        if (claim.getSettledDue() != null) return claim.getSettledDue();
809	        if (claim.isBound()) return claim.getStatedDue();
810	        return live(claim, rates, grade, settings, today);
811	    }
812	
813	    /** The claim's live due at its grade's rate on its date; a correction has no floor. */
814	    public static BigDecimal live(Claim claim, List<Rate> rates, String grade, Settings settings, LocalDate today) {
815	        RoundingMode mode = rounding(claim, settings, today);
816	        return Rate.inForce(rates, grade, claim.getDate())
817	                .map((pct) -> times(claim.getAmount(), pct, mode))
818	                .map((due) -> claim.isCorrection() ? due : due.max(settings.floorOn(claim.getDate())))
819	                .orElse(null);
820	    }
821	
822	    /** How the claim's live figures round, by the date it rounds by and the sheet's policy date. */
823	    public static RoundingMode rounding(Claim claim, Settings settings, LocalDate today) {
824	        return settings.rounding(claim.getRoundDate(), today);
825	    }
826	
827	    /**
828	     * The claim's due with its late charge on top: its figure ({@link #of}) plus the late charge
829	     * an OPEN or PENDING claim gains while overdue on {@code today}. Null for n/a.
830	     */
831	    public static BigDecimal withLate(Claim claim, List<Rate> rates, String grade, Settings settings,
832	            LocalDate today) {
833	        BigDecimal figure = of(claim, rates, grade, settings, today);
834	        return figure == null ? null : figure.add(late(claim, figure, settings, today));
835	    }
836	
837	    /**
838	     * The late charge on a figure: for an OPEN or PENDING claim past its due-by (fixed when it was made)
839	     * on {@code today}, for every full 30 days it is overdue the sheet's late percent in force on
840	     * that boundary date (its due-by plus 30, 60, 90 ... days) of the figure, each rounded to two
841	     * decimals as the claim rounds, added up; else 0.00 (as for a claim deferred on today). Never bound by a statement:
842	     * it follows the sheet's today until the claim is settled.
843	     */
844	    public static BigDecimal late(Claim claim, BigDecimal figure, Settings settings, LocalDate today) {
845	        if (!claim.isOpen() || claim.isDeferredOn(today)) return BigDecimal.ZERO.setScale(2);
846	        return lateAsOpen(claim, figure, settings, today);
847	    }
848	
849	    /** The late charge on a figure as {@link #late} reads it for an open claim, whatever the claim's status. */
850	    public static BigDecimal lateAsOpen(Claim claim, BigDecimal figure, Settings settings, LocalDate today) {
851	        BigDecimal none = BigDecimal.ZERO.setScale(2);
852	        if (figure == null || claim.isCorrection()) return none;
853	        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), today);
854	        long periods = overdue > 0 ? overdue / 30 : 0;
855	        RoundingMode mode = rounding(claim, settings, today);
856	        BigDecimal charge = none;
857	        for (long k = 1; k <= periods; k++) {
858	            BigDecimal pct = settings.latePctOn(claim.getDueBy().plusDays(30 * k));
859	            if (pct.signum() != 0) charge = charge.add(times(figure, pct, mode));
860	        }
861	        return charge;
862	    }
863	
864	    /** The amount times the percent, divided by 100 and rounded to two decimals. */
865	    private static BigDecimal times(BigDecimal amount, BigDecimal pct, RoundingMode mode) {
866	        return amount.multiply(pct).divide(BigDecimal.valueOf(100), 2, mode);
867	    }
868	}
